package com.hau.ai.infrastructure.persistence.entity;import com.hau.ai.domain.model.*;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="ai_jobs")public class AiJobEntity{@Id public UUID id;@Column(name="requested_by",nullable=false)public UUID requestedBy;@Column(name="document_id")public UUID documentId;@Enumerated(EnumType.STRING)@Column(nullable=false)public JobType type;@Enumerated(EnumType.STRING)@Column(nullable=false)public JobStatus status;@Column(name="request_json",columnDefinition="text")public String requestJson;@Column(name="result_reference")public String resultReference;@Column(name="error_code")public String errorCode;@Column(name="error_message")public String errorMessage;@Column(name="created_at",nullable=false)public Instant createdAt;@Column(name="started_at")public Instant startedAt;@Column(name="completed_at")public Instant completedAt;@Column(name="updated_at",nullable=false)public Instant updatedAt;@Version public long version;}
